<?php require_once __DIR__.'/../model/appointment_model.php';require_once __DIR__.'/../model/doctor_model.php';require_once __DIR__.'/../model/auth_model.php';if($_SESSION['user']['role']!=='receptionist')exit('Access denied');$am=new AppointmentModel();$dm=new DoctorModel();$um=new AuthModel();$action=$_GET['action']??'reception';$date=$_GET['date']??date('Y-m-d');$error='';$success='';if($action==='checkin'||$action==='noshow'){$am->status((int)$_GET['id'],$action==='checkin'?'checked-in':'no-show');header('Location:index.php?action=reception&date='.$date);exit;}if($action==='walkin'&&$_SERVER['REQUEST_METHOD']==='POST'){try{$email=trim($_POST['email']);$p=$um->byEmail($email);if(!$p){if(!trim($_POST['name'])||!trim($_POST['phone']))throw new Exception('New patient needs name and phone.');$um->register(trim($_POST['name']),$email,trim($_POST['phone']),'patient123');$p=$um->byEmail($email);}if(!$am->slot((int)$_POST['doctor_id'],$date,$_POST['appointment_time']))throw new Exception('Slot already booked.');$am->create($p['id'],(int)$_POST['doctor_id'],$date,$_POST['appointment_time'],'walk-in');$success='Walk-in booked. New patients use patient123 initially.';}catch(Throwable $e){$error=$e->getMessage();}}$appointments=$am->all($date);$doctors=$dm->all();require __DIR__.'/../views/reception.php';?>